","edit_kind":"method","corrected_code":"    public static EncryptedKey encrypt(SecretKey key, SecretKey plaintext)
            throws NoSuchAlgorithmException, NoSuchPaddingException, InvalidKeyException,
            BadPaddingException, IllegalBlockSizeException, IOException {
        if (key == null) {
            throw new InvalidKeyException("Key is null");
        }
        byte[] nonce = new byte[GCM_NONCE_LENGTH_BYTES];
        SECURE_RANDOM.nextBytes(nonce);
        GCMParameterSpec parameters = new GCMParameterSpec(GCM_TAG_LENGTH_BITS, nonce);

        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        try {
            cipher.init(Cipher.ENCRYPT_MODE, key, parameters);
        } catch (InvalidAlgorithmParameterException e) {
            InvalidKeyException invalidKeyException =
                    new InvalidKeyException("Unable to initialize AES/GCM cipher");
            invalidKeyException.initCause(e);
            throw invalidKeyException;
        }
        return new EncryptedKey(cipher, plaintext);
    }
